//! Deterministic JSON Schema and registry generation.
//!
//! The committed files under `schemas/` are generated by this module and
//! compared byte for byte in the schema-drift test
//! (`crates/pii-eval-contracts/tests/schema_drift.rs`). Output depends only on
//! the Rust types and the pinned `schemars`/`serde_json` versions: object keys
//! are sorted, formatting is `serde_json` pretty printing, and each file ends
//! with a single newline.

use schemars::{JsonSchema, schema_for};
use serde_json::Value;

use crate::artifact::{PublicSyntheticArtifact, RunArtifact};
use crate::corpus::CorpusSnapshot;
use crate::manifest::RunManifest;
use crate::observation::ObservationSet;
use crate::protocol::registry_json;
use crate::reason::ReasonCode;
use crate::version::{DocumentKind, SCHEMA_MAJOR, SCHEMA_MINOR};

/// A generated file: a repository-relative path under `schemas/` and its text.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GeneratedFile {
    /// Path relative to the `schemas/` directory.
    pub path: String,
    /// Exact file contents.
    pub contents: String,
}

fn schema_value<T: JsonSchema>(kind: DocumentKind) -> Value {
    let schema = schema_for!(T);
    let mut value = serde_json::to_value(&schema).unwrap_or(Value::Null);
    if let Value::Object(map) = &mut value {
        map.insert(
            "$id".to_owned(),
            Value::String(format!(
                "urn:pii-eval:schema:{}:{SCHEMA_MAJOR}.{SCHEMA_MINOR}",
                kind.schema_file_stem()
            )),
        );
    }
    value
}

fn render(value: &Value) -> String {
    let mut text = serde_json::to_string_pretty(value).unwrap_or_default();
    text.push('\n');
    text
}

/// The JSON Schema of one document kind.
pub fn json_schema_of(kind: DocumentKind) -> Value {
    match kind {
        DocumentKind::CorpusSnapshot => schema_value::<CorpusSnapshot>(kind),
        DocumentKind::RunManifest => schema_value::<RunManifest>(kind),
        DocumentKind::ObservationSet => schema_value::<ObservationSet>(kind),
        DocumentKind::RunArtifact => schema_value::<RunArtifact>(kind),
        DocumentKind::PublicSyntheticArtifact => schema_value::<PublicSyntheticArtifact>(kind),
    }
}

/// The reason-code catalog as JSON: every stable code, sorted.
pub fn reason_codes_json() -> Value {
    let mut codes: Vec<&str> = ReasonCode::ALL.iter().map(|c| c.as_str()).collect();
    codes.sort_unstable();
    serde_json::json!({
        "schemaVersion": format!("{SCHEMA_MAJOR}.{SCHEMA_MINOR}"),
        "codes": codes,
    })
}

/// Every generated file, in a stable order.
pub fn generated_files() -> Vec<GeneratedFile> {
    let mut files: Vec<GeneratedFile> = DocumentKind::ALL
        .iter()
        .map(|&kind| GeneratedFile {
            path: format!("{}.v{SCHEMA_MAJOR}.schema.json", kind.schema_file_stem()),
            contents: render(&json_schema_of(kind)),
        })
        .collect();
    files.push(GeneratedFile {
        path: "registry/pii-v1.registry.json".to_owned(),
        contents: render(&registry_json()),
    });
    files.push(GeneratedFile {
        path: format!("reason-codes.v{SCHEMA_MAJOR}.json"),
        contents: render(&reason_codes_json()),
    });
    files
}
